import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            while (ptr < len && buffer[ptr] <= ' ') ptr++;
            if (ptr == len) {
                len = in.read(buffer);
                ptr = 0;
            }
            int value = 0;
            while (ptr < len && buffer[ptr] > ' ') {
                value = value * 10 + buffer[ptr++] - '0';
            }
            return value;
        }
    }

    static class Edge {
        int to, cost;

        Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    static class State implements Comparable<State> {
        int city, distance;

        State(int city, int distance) {
            this.city = city;
            this.distance = distance;
        }

        public int compareTo(State other) {
            return Integer.compare(distance, other.distance);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        List<Edge>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int c = fs.nextInt();
            graph[a].add(new Edge(b, c));
            graph[b].add(new Edge(a, c));
        }

        int[] dist = new int[n + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[1] = 0;

        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.add(new State(1, 0));

        while (!pq.isEmpty()) {
            State current = pq.poll();
            if (current.distance != dist[current.city]) continue;
            if (current.city == n) break;

            for (Edge edge : graph[current.city]) {
                int nextDistance = current.distance + edge.cost;
                if (nextDistance < dist[edge.to]) {
                    dist[edge.to] = nextDistance;
                    pq.add(new State(edge.to, nextDistance));
                }
            }
        }

        System.out.println(dist[n]);
    }
}
